testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { headersECors } from './solution.mjs';

const METODOS = 'GET, POST, PUT, DELETE, OPTIONS';

test('config completa monta todos os headers', () => {
  const headers = headersECors({ contentType: 'text/plain', origemPermitida: 'https://meusite.com' });
  assert.deepEqual(headers, {
    'Content-Type': 'text/plain',
    'Access-Control-Allow-Origin': 'https://meusite.com',
    'Access-Control-Allow-Methods': METODOS,
  });
});

test('config vazia usa os padrões', () => {
  assert.deepEqual(headersECors({}), {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': METODOS,
  });
});

test('sem config também usa os padrões', () => {
  assert.deepEqual(headersECors(undefined), {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': METODOS,
  });
});

solutionCode:
export function headersECors(config) {
  const headers = {};

  headers['Content-Type'] = (config && config.contentType) || 'application/json';
  headers['Access-Control-Allow-Origin'] = (config && config.origemPermitida) || '*';
  headers['Access-Control-Allow-Methods'] = 'GET, POST, PUT, DELETE, OPTIONS';

  return headers;
}
